"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97838"],{89326(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.tipo_de_etapa_obrigatorio","status":422,"titulo":"A etapa \xe9 uma se\xe7\xe3o ou um bloco de sistema"},"descricao":{"codigo":"uniplus.estrutura_formulario.tipo_de_etapa_obrigatorio","requisitos":[],"oQueAconteceu":["O `tipo` de uma etapa do formul\xe1rio n\xe3o \xe9 `SECAO` nem `BLOCO`: veio vazio ou com um c\xf3digo que o sistema n\xe3o reconhece. A compara\xe7\xe3o \xe9 exata e diferencia mai\xfasculas de min\xfasculas, ent\xe3o `secao` n\xe3o vale. A se\xe7\xe3o re\xfane itens, e o bloco \xe9 uma parte que o sistema monta. A mensagem \xe9 \\"A etapa \xe9 uma se\xe7\xe3o ou um bloco de sistema. Os tipos aceitos s\xe3o SECAO, BLOCO.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `etapas[i].tipo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. A propriedade `tipo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo.","A estrutura das etapas s\xf3 \xe9 conferida quando todas as etapas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada etapa \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as etapas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as etapas s\xf3 depois que a estrutura das etapas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe `SECAO` para a etapa que re\xfane itens, ou `BLOCO` com o `bloco` desejado para a parte montada pelo sistema, e grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);